package net.wapic.wpcmod.features.general

import com.google.gson.Gson
import com.google.gson.GsonBuilder
import io.github.notenoughupdates.moulconfig.ChromaColour
import net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents
import net.minecraft.network.chat.Component
import net.minecraft.world.entity.Entity
import net.minecraft.world.entity.decoration.ArmorStand
import net.wapic.wpcmod.WpcMod
import net.wapic.wpcmod.config.components.GlowableESPConfig
import net.wapic.wpcmod.features.entity.EspFeature
import net.wapic.wpcmod.util.FileManager
import net.wapic.wpcmod.util.Island
import net.wapic.wpcmod.util.Utils
import net.wapic.wpcmod.util.headTexture
import net.wapic.wpcmod.util.render.state.EntityState
import java.io.File

object CenturyCakeHelper : EspFeature() {

	private val config get() = WpcMod.config.general.centuryCake

	private val EAT_MESSAGE = Regex("^(?:Big )?Yum! You (?:gain|refresh) \\+\\d+. (.+) for 48 hours!$")

	private val eatenCakes = mutableMapOf<CakeType, Long>()
	private const val TWO_DAYS = 172800000

	private val file = File(WpcMod.configDir, "century-cakes.json")
	private val backupFile = File(file.parentFile, "${file.name}.bak")
	private val gson: Gson = GsonBuilder().create()

	fun init() {
		ClientReceiveMessageEvents.GAME.register(::onMessageReceived)
		loadTimes()
	}

	private fun onMessageReceived(message: Component, isActionBar: Boolean) {
		if (isActionBar || Utils.getLocation() != Island.PRIVATE_ISLAND) return

		EAT_MESSAGE.matchEntire(message.string)?.groupValues[1]?.let { stat ->
			WpcMod.LOGGER.debug("Detected Century Cake message with stat: $stat")
			CakeType.entries.find { it.stat == stat }?.let {
				eatenCakes[it] = System.currentTimeMillis() + TWO_DAYS
				WpcMod.LOGGER.debug("Set ${it.name} to ${eatenCakes[it]}")
			}
		}
	}

	override fun compute(entity: Entity): EntityState? {
		if (entity !is ArmorStand) return null

		val cakeType = CakeType.entries.find { it.texture == entity.mainHandItem.headTexture } ?: return null
		eatenCakes[cakeType]?.let { expiration ->
			if (System.currentTimeMillis() < expiration && config.highlightEaten) {
				return EntityState(CakeEatenConfig(config.cakeEatenColor))
			}
		}

		return EntityState(CakeEatenConfig(config.cakeReadyColor))
	}

	override fun isEnabled(): Boolean {
		return Utils.getLocation() == Island.PRIVATE_ISLAND && config.enabled
	}

	private fun loadTimes() {
		val times = FileManager.loadFile<MutableMap<String, Long>>(file, backupFile)
			?: return WpcMod.LOGGER.error("Failed to load century cake times")
		times.forEach { (cakeType, time) ->
			eatenCakes[CakeType.valueOf(cakeType)] = time
			WpcMod.LOGGER.debug("Loaded century cake time for ${cakeType}: $time")
		}
	}

	fun saveTimes() {
		val json = gson.toJson(eatenCakes)
		FileManager.saveFile(json, file, backupFile)
	}

	enum class CakeType(val stat: String, val texture: String) {
		CRAB_COLORED_CENTURY_CAKE(
			"Health",
			""
		),
		PET_ROCK_CENTURY_CAKE(
			"Defense",
			""
		),
		FRUIT_CENTURY_CAKE(
			"Strength",
			""
		),
		POTATO_STYLE_CENTURY_CAKE(
			"Speed",
			""
		),
		BARRY_CENTURY_CAKE(
			"Intelligence",
			""
		),
		SEA_EMPEROR_CENTURY_CAKE(
			"Sea Creature Chance",
			""
		),
		CENTURY_CAKE_OF_THE_NEXT_DUNGEON(
			"Magic Find",
			""
		),
		LATEST_UPDATE_CENTURY_CAKE(
			"Ferocity",
			""
		),
		STREAMERS_CENTURY_CAKE(
			"Pet Luck",
			""
		),
		CHOCOLATE_CENTURY_CAKE(
			"Farming Fortune",
			""
		),
		CLOUDY_CENTURY_CAKE(
			"Foraging Fortune",
			""
		),
		CENTURY_CAKE_OF_HYPE(
			"Mining Fortune",
			""
		),
		UNDEAD_CENTURY_CAKE(
			"Vitality",
			""
		),
		NOT_A_LIE_CENTURY_CAKE(
			"True Defense",
			""
		),
		RIFT_CENTURY_CAKE(
			"Rift Time",
			""
		),
		CORPSE_FLAVORED_CENTURY_CAKE(
			"Cold Resistance",
			""
		),
		CENTURY_CAKE_OF_THE_SEVEN_SEAS(
			"Treasure Chance",
			""
		),
		STARBORN_CENTURY_CAKE(
			"Hunting Fortune",
			""
		),
		LONG_EXPIRED_CENTURY_CAKE(
			"Sweep",
			""
		),
		HEPHAESTUS_CENTURY_CAKE(
			"Tracking",
			""
		);
	}

	class CakeEatenConfig(override var color: ChromaColour) : GlowableESPConfig() {
		init {
			glow = true
		}
	}
}